// spec: specs/addbusiness-step5-invoice-name.md (3.1–3.4) · кейсы: .qa/tests/addbusiness-step5-invoice-name/ADDBIZ-INV-04.md, -05.md
// seed: tests/seed.user.spec.ts · ПРОД: черновик «QA-TEST …» удаляется в afterEach; запуск только с QA_REAL_WRITE=1.
// «שלח» нажимается, но POST …/api/payments ВСЕГДА перехватывается: тело читается, запрос обрывается —
// платёж/LowProfile в Cardcom не создаются, перехода на Cardcom нет. Имя в счёте Morning — только вручную (оплата).
// Необязательная переменная QA_USER_PROFILE_NAME — точное имя профиля user для проверки пустого поля.
import { test, expect, Page } from '@playwright/test';
import {
  FIELD_LABEL, PKG2, PKG3, PayCtl, REAL_WRITE, SKIP_REASON, choosePackageAndGoToStep5, confirmAndSubmit, deleteDraft,
  findCustomerName, goToPackageStep, interceptWithPayments, invoiceField,
} from './invoice-name.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });
test.describe.configure({ mode: 'serial' });

async function emptyField(page: Page, ctl: PayCtl) {
  await goToPackageStep(page, ctl);
  await choosePackageAndGoToStep5(page, PKG2);
  await expect(invoiceField(page), 'поле пустое').toHaveValue('');
  await expect(invoiceField(page), 'поле без ошибки').not.toHaveAttribute('aria-invalid', 'true');
  await confirmAndSubmit(page, ctl);
  // «מה רצוי»: «אפשר להמשיך ולשלוח גם כשהוא ריק» — нет тоста о незаполненных подтверждениях/поле
  await expect(page.getByText('יש לאשר את הצהרת הפרסום לפני הפרסום'), 'нет ошибки валидации').toHaveCount(0);
  const name = findCustomerName(ctl.payments[0]);
  // «אם השדה ריק, הכול עובד כמו היום» — имя профиля (комментарий программиста; факт 02.11)
  expect(typeof name, 'customerName — строка').toBe('string');
  expect((name as string).trim(), 'customerName не пустой (имя профиля)').not.toBe('');
  expect(name as string, 'не тестовое значение поля').not.toContain('QA-AUTO');
  if (process.env.QA_USER_PROFILE_NAME) {
    expect(name, 'customerName = имя профиля').toBe(process.env.QA_USER_PROFILE_NAME);
  }
}

async function filledField(page: Page, ctl: PayCtl) {
  const value = 'QA-AUTO חשבונית בע"מ';
  await goToPackageStep(page, ctl);
  await choosePackageAndGoToStep5(page, PKG3);
  await page.getByLabel(FIELD_LABEL).fill(value);
  await confirmAndSubmit(page, ctl);
  // «מה רצוי»: «אם המשתמש מילא שם, השם שהוא כתב יופיע בחשבונית המס»
  expect(findCustomerName(ctl.payments[0]), 'customerName = введённое имя').toBe(value);
}

test.describe('Публикация бизнеса — шаг 5: имя для счёта в запросе платежа', () => {
  let ctl: PayCtl | null = null;

  test.beforeEach(() => test.skip(!REAL_WRITE, SKIP_REASON));
  test.afterEach(async ({ page }) => {
    if (ctl) await deleteDraft(page, ctl);
    ctl = null;
  });

  test('Пустое поле: «שלח» без ошибок, customerName = имя профиля (платёж оборван) #8bea2a @desktop @data', async ({ page }) => {
    ctl = await interceptWithPayments(page);
    await emptyField(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });

  test('Телефон: пустое поле — «שלח» без ошибок, customerName = имя профиля #8bea2a @android @data', async ({ page }) => {
    ctl = await interceptWithPayments(page);
    await emptyField(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });

  test('Заполненное поле: customerName = введённое имя (платёж оборван) #8bea2a @desktop @data', async ({ page }) => {
    ctl = await interceptWithPayments(page);
    await filledField(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });

  test('Телефон: заполненное поле — customerName = введённое имя #8bea2a @android @data', async ({ page }) => {
    ctl = await interceptWithPayments(page);
    await filledField(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });
});
